async (page) => {
  const results = {};
  let cur = null;
  page.on('pageerror', e => { if (cur) (results[cur] ||= []).push('pageerror: ' + e.message); });
  page.on('console', m => { if (cur && m.type()==='error') (results[cur] ||= []).push('console: ' + m.text()); });
  await page.evaluate(() => {
    window.__ev = [];
    window.addEventListener('error', e => window.__ev.push(['exception', e.message]));
    window.addEventListener('unhandledrejection', e => window.__ev.push(['promise-rejection', String(e.reason && e.reason.message || e.reason)]));
  });
  const buttons = await page.locator('button').all();
  const labels = [];
  for (const b of buttons) labels.push(await b.innerText());
  const out = {};
  for (let i=0;i<buttons.length;i++) {
    cur = labels[i];
    await page.evaluate(() => window.__ev = []);
    await buttons[i].click();
    await page.waitForTimeout(1500);
    out[i + ':' + labels[i]] = { ev: await page.evaluate(() => window.__ev), pw: results[cur] || [] };
    results[cur] = [];
  }
  return out;
}

